@bp.route('/api/coffeeshops', methods=['POST'])
def create_coffee_shop():
    data = request.get_json()
    new_coffee_shop = CoffeeShop(name=data['name'], address=data['address'], phone=data['phone'], email=data['email'], menu=data['menu'], contact_info=data['contact_info'])
    new_coffee_shop.save()
    return jsonify({'success': True, 'data': {'id': new_coffee_shop.id}}), 201

@bp.route('/api/coffeeshops/<int:item_id>', methods=['PUT'])
def update_coffee_shop(item_id):
    data = request.get_json()
    coffee_shop = CoffeeShop.query.get(item_id)
    if not coffee_shop:
        return jsonify({'success': False, 'error': 'Coffee shop not found'}), 404
    coffee_shop.name = data['name']
    coffee_shop.address = data['address']
    coffee_shop.phone = data['phone']
    coffee_shop.email = data['email']
    coffee_shop.menu = data['menu']
    coffee_shop.contact_info = data['contact_info']
