    return jsonify({'success': True, 'data': {'id': coffee_shop.id}})

@bp.route('/api/coffeeshops/<int:item_id>', methods=['DELETE'])
def delete_coffee_shop(item_id):
    coffee_shop = CoffeeShop.query.get(item_id)
    if not coffee_shop:
        return jsonify({'success': False, 'error': 'Coffee shop not found'}), 404
    coffee_shop.delete()
    return jsonify({'success': True})
